mapper.select:
select DISTINCT b.allocation_id as name
from sys_user a,
sys_user_allocation b
where a.USER_ID = b.user_id

    and a.user_id=#{projectAssistant}

order by b.employee_assign_id

select DISTINCT b.allocation_id as name
from sys_user a,
sys_user_allocation b
where a.USER_ID = b.user_id

    and b.employee_assign_id=#{employeeAssignId}

order by b.employee_assign_id

select DISTINCT b.allocation_id as name
from sys_user a,
sys_user_allocation b
where a.USER_ID = b.user_id

    and b.user_id=#{userId}

select employee_assign_id from fnd_employee_assigns where 1=1
and employee_id=#{employeeId}
order by employee_assign_id

select fea.employee_assign_id, em.employee_id, em.employee_code, em.company_id, em.name, em.email, em.mobil, em.phone, em.id_type, em.id_card_no, em.enabled_flag, fou.unit_name as unit_name, fc.company_full_name as company_name, fou.unit_id as unit_id, ( select Max(fe.name) from fnd_employee fe, fnd_employee_assigns feas where fe.employee_id=feas.employee_id and feas.unit_id=fou.unit_id and feas.position_id=fop.position_id )as manager_name from fnd_employee em, fnd_employee_assigns fea, fnd_org_position fop, fnd_org_unit fou, fnd_company fc
em.employee_id=fea.employee_id and fou.unit_id = fea.unit_id and fop.position_id=fou.chief_position_id and fc.company_id=em.company_id and em.employee_code != #{request.employeeCode}
and em.employee_id = #{employeeId}
and em.employee_code like concat(concat('%',#{employeeCode}),'%')
and em.company_id = #{companyId}
and em.name like concat(concat('%',#{name}),'%')
and fop.position_id=#{positionId}
and em.name!=#{projectManagerName}
and fou.unit_type in('SALES')

select DISTINCT em.employee_id , ( select fc.company_short_name from fnd_company fc where fc.company_id = fou.company_id )company_name, fop.position_name, fou.unit_name, em.employee_code , em.company_id , em.name as name, em.email as email, em.mobil as mobil, em.phone as phone, em.id_type , em.id_card_no , em.enabled_flag from fnd_employee em left join fnd_employee_assigns fea on em.employee_id = fea.employee_id left join fnd_org_position fop on fop.position_id = fea.position_id left join fnd_org_unit fou on fou.unit_id = fop.unit_id
em.enabled_flag = 'Y'
AND fea.UNIT_ID = #{unitId}
and em.employee_id = #{employeeId}
and em.employee_code like concat(concat('%',#{employeeCode}),'%')
and em.company_id = #{request.companyId}
and em.name like concat(concat('%',#{name}),'%')
and fop.position_id=#{positionId}
and em.name!=#{projectManagerName}
and em.employee_code not in (#{codeString})
and fou.unit_type= #{unitType}

select DISTINCT em.employee_id , ( select fc.company_short_name from fnd_company fc where fc.company_id = fou.company_id )company_name, fop.position_name, fou.unit_name, em.employee_code , em.company_id , em.name as name, em.email as email, em.mobil as mobil, em.phone as phone, em.id_type , em.id_card_no , em.enabled_flag from fnd_employee em left join fnd_employee_assigns fea on em.employee_id = fea.employee_id left join fnd_org_position fop on fop.position_id = fea.position_id left join fnd_org_unit fou on fou.unit_id = fop.unit_id
em.enabled_flag = 'Y' and fea.unit_id in (10324,10331)
and em.employee_id = #{employeeId}
and em.employee_code like concat(concat('%',#{employeeCode}),'%')
and em.company_id = #{request.companyId}
and em.name like concat(concat('%',#{name}),'%')
and fou.unit_name like concat(concat('%',#{unitName}),'%')
and fop.position_id=#{positionId}
and em.name!=#{projectManagerName}

SELECT sua.ALLOCATION_ID as name FROM sys_user_allocation sua, sys_user su WHERE su.user_id = sua.user_id
AND sua.employee_assign_id = ( SELECT fea.employee_assign_id FROM fnd_employee_assigns fea ,fnd_employee fe WHERE fea.position_id = ( SELECT fop.position_id FROM fnd_org_position fop WHERE fop.unit_id = #{manageUnitId} AND fop.chief_position_flag = 'Y' ) and fea.employee_id = fe.employee_id
)

select e.EMPLOYEE_ID, e.NAME, e.EMPLOYEE_CODE from fnd_employee_assigns t, fnd_employee e where 1=1
and t.company_id=#{companyId}
and t.company_id=#{request.companyId}
and position_id in (77,44) and t.employee_id=e.EMPLOYEE_ID
and e.employee_code like concat('%',concat(#{employeeCode},'%'))
and e.name like concat('%',concat(#{name},'%'))

SELECT FE.EMPLOYEE_ID, FE.NAME, FE.EMPLOYEE_CODE, FE.COMPANY_ID, FEA.UNIT_ID, FOU.UNIT_CODE, fou.unit_name, FOP.POSITION_CODE FROM FND_EMPLOYEE FE LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID LEFT JOIN FND_ORG_POSITION FOP ON FOP.POSITION_ID = FEA.POSITION_ID
1 = 1
and FE.EMPLOYEE_CODE = #{employeeCode}

select fe.* from
FND_EMPLOYEE_ASSIGNS fea,
FND_ORG_POSITION fop,
FND_EMPLOYEE fe
WHERE fea.EMPLOYEE_ID = fe.EMPLOYEE_ID
and fop.POSITION_ID = fea.POSITION_ID

    and fop.POSITION_CODE in

        #{item}



    and fe.EMPLOYEE_CODE = #{employeeCode}


    and fe.COMPANY_ID = #{companyId}

select
distinct su.user_id,su.user_name,su.description as name,
fea.employee_assign_id,fea.employee_id
from sys_user su,
sys_user_allocation sua,
fnd_employee_assigns fea
where fea.unit_id=#{unitId}
and su.user_id=sua.user_id
and fea.employee_assign_id=sua.employee_assign_id
and fea.company_id=sua.company_id
and fea.company_id=#{companyId}

    and su.user_id=#{userId}

SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM FND_ORG_POSITION FOP JOIN FND_EMPLOYEE_ASSIGNS FEA ON FOP.POSITION_ID=FEA.POSITION_ID AND FOP.ENABLED_FLAG='Y' JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID AND FE.ENABLED_FLAG='Y' WHERE FOP.POSITION_CODE IN （'05230','00130','05530','00320','01700','05000'） AND FE.COMPANY_ID=#{companyId} UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM FCT_CONTRACT FC JOIN FCT_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN FND_EMPLOYEE_ASSIGNS FEA ON FEA.EMPLOYEE_ASSIGN_ID=FP.PROJECT_ASSISTANT_ASSIGNS_ID JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID WHERE 1=1 AND FC.CONTRACT_ID=#{contractId}
UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM FCT_CONTRACT FC JOIN FCT_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FP.EMPLOYEE_ID WHERE 1=1 AND FC.CONTRACT_ID=#{contractId}
UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM CON_CONTRACT FC JOIN PRJ_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN FND_EMPLOYEE_ASSIGNS FEA ON FEA.EMPLOYEE_ASSIGN_ID=(select fea.employee_assign_id from sys_user_allocation sua where sua.user_id = fp.assist_project_manager and sua.user_id = fp.assist_unit_id) JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID WHERE 1=1 AND FC.CONTRACT_ID=#{contractId}
UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM CON_CONTRACT FC JOIN PRJ_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FP.EMPLOYEE_ID WHERE 1=1 AND FC.CONTRACT_ID=#{contractId}
UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM FND_ORG_UNIT FOU, FND_EMPLOYEE_ASSIGNS FEA, FND_EMPLOYEE FE WHERE FOU.UNIT_ID = #{unitId} AND FEA.UNIT_ID=FOU.PARENT_UNIT_ID AND FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID
UNION
SELECT FE.EMPLOYEE_ID, FE.EMPLOYEE_CODE FROM FND_ORG_UNIT FOU JOIN FND_ORG_POSITION FOP ON FOU.CHIEF_POSITION_ID=FOP.POSITION_ID AND FOU.ENABLED_FLAG='Y' JOIN FND_EMPLOYEE_ASSIGNS FEA ON FOP.POSITION_ID=FEA.POSITION_ID AND FOP.ENABLED_FLAG='Y' AND FEA.ENABLED_FLAG='Y' JOIN FND_EMPLOYEE FE ON FE.EMPLOYEE_ID=FEA.EMPLOYEE_ID AND FE.ENABLED_FLAG='Y' WHERE FOU.UNIT_ID=#{unitId}

select DISTINCT a.USER_NAME as name
from sys_user a,
sys_user_allocation b
where a.USER_ID = b.user_id



and b.employee_assign_id in

    #{item}

SELECT DISTINCT a.USER_NAME AS name FROM fnd_employee_assigns fea, fnd_org_unit fou, fnd_employee_assigns leader, sys_user_allocation b, sys_user a WHERE fou.unit_id = fea.unit_id AND fou.chief_position_id = leader.position_id AND a.USER_ID = b.user_id AND b.employee_assign_id=leader.employee_assign_id
and fea.employee_assign_id in
#{item}

select DISTINCT a.USER_NAME as name
from sys_user a,
sys_user_allocation b
where a.USER_ID = b.user_id

    and b.company_id =#{companyId}

and b.employee_assign_id in(#{employeeAssignId},#{assistantAssignId})

SELECT sua.allocation_id as name
  FROM sys_user_allocation sua, sys_user su
 where su.user_id = sua.user_id
   and sua.allocation_id = #{allocationId}

    and sua.company_id = #{companyId}
